mapper.select:
WITH promoted AS (
    UPDATE student s SET grade=s.grade+1, grade_changed_at=#{now}, updated_at=#{now}
    WHERE s.status='ACTIVE' AND NOT s.is_demo AND s.grade BETWEEN 3 AND 8
      AND COALESCE(s.grade_changed_at, s.created_at) < #{cutoff}
      AND NOT EXISTS(SELECT 1 FROM student_grade_promotion p WHERE p.student_id=s.id AND p.school_year=#{year})
    RETURNING s.id, s.nickname, s.grade-1 AS from_grade, s.grade AS to_grade
), recorded AS (
    INSERT INTO student_grade_promotion(student_id,school_year,from_grade,to_grade,promoted_at)
    SELECT id,#{year},from_grade,to_grade,#{now} FROM promoted
    RETURNING student_id
)
SELECT p.id AS student_id, p.nickname, p.from_grade, p.to_grade
FROM promoted p JOIN recorded r ON r.student_id=p.id ORDER BY p.id
